-- Batas kelurahan/desa (poligon) wilayah layanan awal: Kota + Kab. Magelang.
-- Dipakai untuk: titik peta tujuan → kelurahan/desa-nya (batas wilayah dari
-- lokasi rumah, bukan cuma pilihan dropdown), jarak dari titik tengah kelurahan
-- kalau titik peta tidak diisi, dan peta wilayah layanan.
-- path: JSON [[[lat,lng], ...], ...] (ring luar & lubang, dibaca even-odd),
-- disederhanakan ±3 m. Data: github.com/cahyadsn/wilayah_boundaries (MIT).
CREATE TABLE region_boundaries (
    code VARCHAR(13) NOT NULL PRIMARY KEY,
    lat DOUBLE NOT NULL,
    lng DOUBLE NOT NULL,
    path MEDIUMTEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

